const n = rng.int(2, 4);
const [g, dg] = rng.pick([["\\sin x", "\\cos x"], ["\\cos x", "-\\sin x"], ["e^{x}", "e^{x}"], ["\\ln x", "\\frac{1}{x}"]]);
const xn = `x^{${n}}`, xn1 = n - 1 === 1 ? "x" : `x^{${n - 1}}`;
const d = dg.startsWith("-") ? `${n}${xn1} ${g} - ${xn} ${dg.slice(1)}` : `${n}${xn1} ${g} + ${xn} \\cdot ${dg}`;
return {
  prompt: `Differentiate $f(x) = ${xn} ${g}$.`,
  answers: [d],
  explanation: `Product rule, $(uv)' = u'v + uv'$ with $u = ${xn}$ and $v = ${g}$: $$f'(x) = ${d}$$ Any equivalent form is accepted.`,
};

const sg = (k) => (k < 0 ? `- ${-k}` : `+ ${k}`);
const px = rng.int(-4, 4), py = rng.int(-4, 5), m = rng.pick([-3, -2, -1, 2, 3, 4]);
const b = py - m * px;
const ys = b === 0 ? `y = ${m}x` : `y = ${m}x ${sg(b)}`;
return {
  prompt: `Write an equation of the line through $(${px}, ${py})$ with slope $${m}$.`,
  answers: [ys],
  explanation: `Point-slope form $y ${sg(-py)} = ${m}(x ${sg(-px)})$ is the same line as $${ys}$. Any equation of this line is accepted.`,
};

