let a = 0, b = 0;
while (a === 0 || b === 0 || a === b) { a = rng.int(-7, 7); b = rng.int(-7, 7); }
const p = -(a + b), q = a * b;
const poly = `x^{2}${p === 0 ? "" : ` ${p < 0 ? "-" : "+"} ${Math.abs(p) === 1 ? "" : Math.abs(p)}x`} ${sg(q)}`;
const f = `(x ${sg(-a)})(x ${sg(-b)})`;
return {
  prompt: `Factor $${poly}$.`,
  answers: [f],
  explanation: `Two numbers that multiply to $${q}$ and add to $${p}$: $${-a}$ and $${-b}$, so $${poly} = ${f}$. The expanded form is equivalent but isn't factored, so it only gets half credit.`,
};

